-- Consulta: VendaComissaoVendedor
-- Tipo: Acréscimo (64)
-- Parâmetros: Formulários!VendaImovelVendido!VendaCondPagto.Formulário!LinkVenda (Texto), Formulários!VendaImovelVendido!Vendedor (Texto), Formulários!VendaImovelVendido!ValorParcelaComissao (Texto), Formulários!VendaImovelVendido!DataVenda (Texto), Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Documento (Texto), Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Complemento (Texto), Formulários!VendaImovelVendido!NomeVinculada (Texto), Formulários!VendaImovelVendido!CodImovel (Texto), Formulários!VendaImovelVendido!VendaCondPagto.Formulário!VenctoParcela (Texto), Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Integracao (Texto), Formulários!VendaImovelVendido!EmpVinculada (Texto)
-- Descrição: 

INSERT INTO TempVendaImovel ( LinkVenda, EmpVinculada, CodigoParceiro, ContaFinanceira, ValorCredito, DataMovto, CodImovel, CodHistorico, Plano3, NumDoc, Complemento, AgrupadorVenda, DataVencto, Integracao, ClassificacaoVenda, CodAtribuiEmpresa, CodAnteriorEmpresa, IndiceReajuste )
SELECT Formulários!VendaImovelVendido!VendaCondPagto.Formulário!LinkVenda AS Link, "1" AS Empresa, Formulários!VendaImovelVendido!Vendedor AS Parceiro, "1" AS Financeira, Formulários!VendaImovelVendido!ValorParcelaComissao AS ValorDeb, Formulários!VendaImovelVendido!DataVenda AS DtMov, "1" AS Imovel, "5" AS Historico, "1" AS Plano3, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Documento AS Doc, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Complemento & " - " & Formulários!VendaImovelVendido!NomeVinculada AS Complem, Formulários!VendaImovelVendido!CodImovel AS Agrupar, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!VenctoParcela AS Vencto, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Integracao AS Integra, "D" AS Classifica, Formulários!VendaImovelVendido!EmpVinculada AS AtribuiEmpresa, "1" AS EmpresaAnterior, "1" AS IndiceReajuste;
